-- Private-workspace guard: use analysis/run_private.py after preparation.
\if :{?CUFF_PREPARED_WORKSPACE}
\else
\echo 'Use the prepared-workspace launcher; extraction is disabled in the checkout.'
\quit 3
\endif

\set ON_ERROR_STOP on
SET default_transaction_read_only=on;
SET max_parallel_workers_per_gather=2;
\copy (SELECT * FROM public.patient) TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_stays.csv' CSV HEADER
\copy (SELECT * FROM public.infusiondrug WHERE drugname IN ('DOPamine MAX 800 mg Dextrose 5% 250 ml  Premix (mcg/kg/min)','DOPamine STD 15 mg Dextrose 5% 250 ml  Premix (mcg/kg/min)','DOPamine STD 400 mg Dextrose 5% 250 ml  Premix (mcg/kg/min)','DOPamine STD 400 mg Dextrose 5% 500 ml  Premix (mcg/kg/min)','Dopamine','Dopamine ()','Dopamine (Unknown)','Dopamine (mcg/hr)','Dopamine (mcg/kg/hr)','Dopamine (mcg/kg/min)','Dopamine (mcg/min)','Dopamine (mg/hr)','Dopamine (ml/hr)','Dopamine (nanograms/kg/min)','EPINEPHrine(Adrenalin)MAX 30 mg Sodium Chloride 0.9% 250 ml (mcg/min)','EPINEPHrine(Adrenalin)STD 4 mg Sodium Chloride 0.9% 250 ml (mcg/min)','EPINEPHrine(Adrenalin)STD 4 mg Sodium Chloride 0.9% 500 ml (mcg/min)','EPINEPHrine(Adrenalin)STD 7 mg Sodium Chloride 0.9% 250 ml (mcg/min)','Epinepherine (mcg/min)','Epinephrine','Epinephrine ()','Epinephrine (mcg/hr)','Epinephrine (mcg/kg/min)','Epinephrine (mcg/min)','Epinephrine (mg/hr)','Epinephrine (mg/kg/min)','Epinephrine (ml/hr)','Levophed (mcg/kg/min)','Levophed (mcg/min)','Levophed (mg/hr)','Levophed (ml/hr)','NEO-SYNEPHRINE (mcg/min)','Neo Synephrine (mcg/min)','Neo-Synephrine (mcg/min)','NeoSynephrine (mcg/min)','Neosynephrine (mcg/min)','Neosynephrine (ml/hr)','Norepinephrine','Norepinephrine ()','Norepinephrine (Unknown)','Norepinephrine (mcg/hr)','Norepinephrine (mcg/kg/hr)','Norepinephrine (mcg/kg/min)','Norepinephrine (mcg/min)','Norepinephrine (mg/hr)','Norepinephrine (mg/kg/min)','Norepinephrine (mg/min)','Norepinephrine (ml/hr)','Norepinephrine (units/min)','Norepinephrine MAX 32 mg Dextrose 5% 250 ml (mcg/min)','Norepinephrine MAX 32 mg Dextrose 5% 500 ml (mcg/min)','Norepinephrine STD 32 mg Dextrose 5% 282 ml (mcg/min)','Norepinephrine STD 32 mg Dextrose 5% 500 ml (mcg/min)','Norepinephrine STD 4 mg Dextrose 5% 250 ml (mcg/min)','Norepinephrine STD 4 mg Dextrose 5% 500 ml (mcg/min)','Norepinephrine STD 8 mg Dextrose 5% 250 ml (mcg/min)','Norepinephrine STD 8 mg Dextrose 5% 500 ml (mcg/min)','Phenylephrine','Phenylephrine  MAX 100 mg Sodium Chloride 0.9% 250 ml (mcg/min)','Phenylephrine  STD 20 mg Sodium Chloride 0.9% 250 ml (mcg/min)','Phenylephrine  STD 20 mg Sodium Chloride 0.9% 500 ml (mcg/min)','Phenylephrine ()','Phenylephrine (mcg/hr)','Phenylephrine (mcg/kg/min)','Phenylephrine (mcg/kg/min) (mcg/kg/min)','Phenylephrine (mcg/min)','Phenylephrine (mcg/min) (mcg/min)','Phenylephrine (mg/hr)','Phenylephrine (mg/kg/min)','Phenylephrine (ml/hr)','VAsopressin (units/min)','Vasopressin','Vasopressin ()','Vasopressin (Unknown)','Vasopressin (mcg/kg/min)','Vasopressin (mcg/min)','Vasopressin (mg/hr)','Vasopressin (mg/min)','Vasopressin (ml/hr)','Vasopressin (units/hr)','Vasopressin (units/kg/min)','Vasopressin (units/min)','Vasopressin 20 Units Sodium Chloride 0.9% 100 ml (units/hr)','Vasopressin 20 Units Sodium Chloride 0.9% 250 ml (units/hr)','Vasopressin 40 Units Sodium Chloride 0.9% 100 ml (Unknown)','Vasopressin 40 Units Sodium Chloride 0.9% 100 ml (units/hr)','Vasopressin 40 Units Sodium Chloride 0.9% 100 ml (units/kg/hr)','Vasopressin 40 Units Sodium Chloride 0.9% 100 ml (units/min)','Vasopressin 40 Units Sodium Chloride 0.9% 200 ml (units/min)','dopamine (mcg/kg/min)','levophed  (mcg/min)','levophed (mcg/min)','levophed (ml/hr)','neo-synephrine (mcg/min)','neosynephrine (mcg/min)','vasopressin (ml/hr)','vasopressin (units/min)')) TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_drugs.csv' CSV HEADER
\copy (SELECT vitalperiodicid,patientunitstayid,observationoffset,systemicsystolic,systemicdiastolic,systemicmean FROM public.vitalperiodic WHERE systemicmean IS NOT NULL OR systemicsystolic IS NOT NULL OR systemicdiastolic IS NOT NULL) TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_art.csv' CSV HEADER
\copy (SELECT vitalaperiodicid,patientunitstayid,observationoffset,noninvasivesystolic,noninvasivediastolic,noninvasivemean FROM public.vitalaperiodic WHERE noninvasivemean IS NOT NULL OR noninvasivesystolic IS NOT NULL OR noninvasivediastolic IS NOT NULL) TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_cuff.csv' CSV HEADER
\copy (SELECT patientunitstayid,nursingchartoffset,nursingchartcelltypevallabel,nursingchartcelltypevalname,nursingchartvalue FROM public.nursecharting WHERE concat_ws(' ',nursingchartcelltypevallabel,nursingchartcelltypevalname) ~* 'rhythm') TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_rhythm.csv' CSV HEADER
\copy (SELECT DISTINCT patientunitstayid,diagnosisstring FROM public.diagnosis WHERE diagnosisstring ~* 'atrial fibrillation|atrial fibr') TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_af_dx.csv' CSV HEADER
\copy (SELECT patientunitstayid,treatmentoffset,treatmentstring FROM public.treatment WHERE treatmentstring ~* 'arterial.*catheter|arterial.*line') TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_arterial_line.csv' CSV HEADER
\copy (SELECT p.hospitalid,count(DISTINCT p.patientunitstayid) AS all_stays,count(DISTINCT i.patientunitstayid) AS infusion_any_stays FROM public.patient p LEFT JOIN (SELECT DISTINCT patientunitstayid FROM public.infusiondrug) i USING(patientunitstayid) GROUP BY p.hospitalid) TO '@CUFF_WORKSPACE@/phase0/_restricted/eicu_hospital_infusion_coverage.csv' CSV HEADER
